-- Contenido inicial de la página "Términos y Condiciones".
-- ON CONFLICT DO NOTHING: no sobreescribe si ya hay contenido cargado (ej. editado desde el admin).
INSERT INTO settings (key, value, description)
VALUES (
  'terms_page',
  '{
    "updated_at": "2026-08-14T00:00:00.000Z",
    "title_es": "Términos y Condiciones",
    "title_en": "Terms and Conditions",
    "body_es": "Última actualización: 14 de agosto de 2026\n\n1. OBJETO Y ACEPTACIÓN\nEstos Términos y Condiciones regulan el uso de la plataforma Tango QR (en adelante, \"la Plataforma\") y la contratación de experiencias de cena-show de tango en Buenos Aires a través de ella. Al acceder a la Plataforma, reservar o comprar una experiencia, el usuario declara haber leído, entendido y aceptado estos Términos en su totalidad. Si no está de acuerdo con alguna de sus cláusulas, le pedimos que no utilice la Plataforma.\n\n2. QUIÉNES SOMOS\nTango QR es una plataforma de venta y gestión de reservas que conecta a los pasajeros con casas de tango y espacios asociados en Buenos Aires. No somos propietarios ni operadores de las casas de tango: actuamos como intermediarios entre el pasajero y el operador de cada experiencia, quien es el responsable de brindar el servicio contratado (cena, show, bebidas y demás prestaciones detalladas en cada opción).\n\n3. ACCESO A LA PLATAFORMA\nEl acceso a la Plataforma es exclusivo para pasajeros referidos por un recomendador autorizado (hotel, conserjería, agencia o vendedor con código propio). Sin un código de recomendador activo no es posible navegar el catálogo ni realizar una reserva. El código utilizado queda asociado a la reserva a todos los efectos de trazabilidad y comisiones, y no afecta el precio final que paga el pasajero.\n\n4. RESERVAS Y CONFIRMACIÓN\nLa reserva se considera confirmada una vez acreditado el pago (Mercado Pago o PIX) o, en el caso de pago en efectivo, una vez que el recomendador confirma haber recibido el cobro. El pasajero recibirá un email de confirmación con un voucher que incluye un código QR de verificación: es el comprobante que debe presentar en la casa de tango el día de la experiencia. Cada opción de reserva indica sus propios días y horarios de disponibilidad, cupos y condiciones (por ejemplo, si incluye cena, traslado o es solo show); es responsabilidad del pasajero revisar estos datos antes de confirmar.\n\n5. PRECIOS Y MEDIOS DE PAGO\nLos precios se publican de referencia en dólares estadounidenses (USD). Según el medio de pago elegido, el cobro se procesa en pesos argentinos (ARS) a través de Mercado Pago, o en reales brasileños (BRL) a través de PIX, ambos convertidos al tipo de cambio vigente en el momento de la compra. El pago en efectivo se coordina directamente con el recomendador, en la moneda y monto que este informe. Los precios pueden variar sin aviso previo hasta el momento en que se confirma y paga la reserva; una vez confirmada, el precio pagado no sufre modificaciones.\n\n6. TRASLADOS\nAlgunas experiencias incluyen traslado de ida y vuelta desde hoteles de determinadas zonas de la Ciudad de Buenos Aires (Centro, Recoleta, Puerto Madero, San Telmo, Palermo y Retiro, según la casa), ya sea incluido en el precio o como servicio opcional con costo adicional. El pasajero debe indicar su hotel y número de habitación al reservar para que el traslado pueda coordinarse; si su alojamiento no está dentro de las zonas de cobertura, deberá acordar un punto de encuentro cercano con el operador. Los horarios de pickup son aproximados y pueden ajustarse por motivos operativos (tránsito, clima, cantidad de pasajeros).\n\n7. MODIFICACIÓN DE RESERVAS\nEl pasajero puede solicitar la modificación de fecha, cantidad de personas u otros datos de su reserva dentro de la ventana de tiempo indicada en el email de confirmación, sujeto a disponibilidad de la nueva fecha u opción elegida. Las modificaciones que impliquen una diferencia de precio se cobran o reintegran según corresponda.\n\n8. CANCELACIONES Y REINTEGROS\nEl pasajero puede solicitar la cancelación de su reserva dentro de la ventana de tiempo indicada en el email de confirmación, a través del link de gestión incluido en ese mismo email. Las cancelaciones realizadas dentro de esa ventana dan lugar al reintegro del pago, cuando este se haya realizado por Mercado Pago o PIX, a través del mismo medio utilizado para pagar. Las cancelaciones fuera de esa ventana, las inasistencias sin aviso (\"no-show\") y los pagos coordinados en efectivo con el recomendador quedan sujetos a la política particular informada en cada caso, y pueden no dar derecho a reintegro. Tango QR se reserva el derecho de cancelar o reprogramar una reserva por causas ajenas a su voluntad (por ejemplo, cierre de la casa de tango, causas de fuerza mayor), en cuyo caso se ofrecerá reprogramación o reintegro total.\n\n9. DATOS DEL PASAJERO\nPara emitir el voucher y permitir el ingreso a la experiencia, se solicitan datos del pasajero titular de la reserva (nombre, DNI o documento equivalente, email y, opcionalmente, teléfono). Es responsabilidad del pasajero que estos datos sean correctos y que coincidan con el documento que presentará el día de la experiencia.\n\n10. RECOMENDADORES\nLos recomendadores (hoteles, conserjerías, agencias o personas con código propio) actúan de forma independiente y no son empleados, representantes ni socios de Tango QR. Su función es difundir las experiencias mediante su código o QR personal y, en algunos casos, gestionar el cobro en efectivo en nombre del operador. Tango QR no se responsabiliza por acuerdos, promesas o información brindada por un recomendador que no esté reflejada en estos Términos o en el detalle de cada experiencia publicado en la Plataforma.\n\n11. PROPIEDAD INTELECTUAL\nEl nombre, logo, diseño y contenidos de la Plataforma son propiedad de Tango QR o de sus licenciantes, y están protegidos por la normativa vigente en materia de propiedad intelectual. Queda prohibida su reproducción, distribución o uso comercial sin autorización previa y por escrito.\n\n12. LIMITACIÓN DE RESPONSABILIDAD\nTango QR facilita la reserva y el pago de experiencias operadas por terceros. La prestación del servicio en sí (cena, show, bebidas, calidad artística, condiciones del local) es responsabilidad de la casa de tango correspondiente. Tango QR no responde por daños indirectos, pérdida de disfrute u otros perjuicios derivados de la prestación del servicio por parte del operador, sin perjuicio de acompañar al pasajero en el reclamo correspondiente ante el operador cuando así se le solicite.\n\n13. MODIFICACIONES DE ESTOS TÉRMINOS\nTango QR puede actualizar estos Términos y Condiciones en cualquier momento para reflejar cambios operativos, legales o del servicio. La versión vigente es siempre la publicada en esta misma página, con su fecha de última actualización. El uso continuado de la Plataforma luego de una actualización implica la aceptación de los nuevos términos.\n\n14. LEY APLICABLE Y JURISDICCIÓN\nEstos Términos se rigen por las leyes de la República Argentina. Para cualquier controversia derivada de su interpretación o aplicación, las partes se someten a la jurisdicción de los tribunales ordinarios de la Ciudad Autónoma de Buenos Aires, sin perjuicio de los derechos que asistan al consumidor conforme a la normativa de defensa del consumidor vigente.\n\n15. CONTACTO\nAnte cualquier consulta sobre estos Términos y Condiciones o sobre una reserva en particular, podés escribirnos por email desde la sección Contacto de la Plataforma.",
    "body_en": "Last updated: August 14, 2026\n\n1. PURPOSE AND ACCEPTANCE\nThese Terms and Conditions govern the use of the Tango QR platform (the \"Platform\") and the booking of tango dinner-show experiences in Buenos Aires through it. By accessing the Platform, booking, or purchasing an experience, the user confirms having read, understood, and accepted these Terms in full. If you do not agree with any of these clauses, please refrain from using the Platform.\n\n2. WHO WE ARE\nTango QR is a booking and sales platform that connects travelers with partner tango houses and venues in Buenos Aires. We do not own or operate the tango houses: we act as an intermediary between the traveler and the operator of each experience, who is responsible for providing the contracted service (dinner, show, drinks, and any other inclusions detailed in each option).\n\n3. ACCESS TO THE PLATFORM\nAccess to the Platform is exclusive to travelers referred by an authorized seller (a hotel, concierge, agency, or individual with their own code). Without an active seller code, it is not possible to browse the catalog or make a booking. The code used is linked to the booking for tracking and commission purposes only, and does not affect the final price paid by the traveler.\n\n4. BOOKINGS AND CONFIRMATION\nA booking is considered confirmed once payment is received (via Mercado Pago or PIX) or, for cash payments, once the seller confirms having collected payment. The traveler will receive a confirmation email with a voucher that includes a verification QR code — this is the proof of purchase to present at the tango house on the day of the experience. Each booking option lists its own available days, times, capacity, and conditions (for example, whether dinner or transfer is included, or whether it''s show-only); it is the traveler''s responsibility to review these details before confirming.\n\n5. PRICES AND PAYMENT METHODS\nPrices are published for reference in US dollars (USD). Depending on the payment method chosen, charges are processed in Argentine pesos (ARS) via Mercado Pago, or in Brazilian reais (BRL) via PIX, both converted at the exchange rate in effect at the time of purchase. Cash payments are coordinated directly with the seller, in the currency and amount they specify. Prices may change without prior notice up until the booking is confirmed and paid; once confirmed, the price paid does not change.\n\n6. TRANSFERS\nSome experiences include round-trip transfer from hotels in certain areas of Buenos Aires (Downtown, Recoleta, Puerto Madero, San Telmo, Palermo, and Retiro, depending on the venue), either included in the price or as an optional paid add-on. Travelers must provide their hotel and room number when booking so the transfer can be coordinated; if their accommodation falls outside the coverage areas, they must agree on a nearby meeting point with the operator. Pickup times are approximate and may be adjusted for operational reasons (traffic, weather, number of travelers).\n\n7. BOOKING CHANGES\nTravelers may request changes to the date, number of guests, or other booking details within the time window stated in the confirmation email, subject to availability of the new date or option. Changes that result in a price difference will be charged or refunded accordingly.\n\n8. CANCELLATIONS AND REFUNDS\nTravelers may request cancellation of their booking within the time window stated in the confirmation email, via the management link included in that same email. Cancellations made within that window are eligible for a refund, when payment was made via Mercado Pago or PIX, through the same method used to pay. Cancellations made outside that window, no-shows, and payments arranged in cash with the seller are subject to the specific policy communicated in each case, and may not be eligible for a refund. Tango QR reserves the right to cancel or reschedule a booking for reasons beyond its control (for example, tango house closure or force majeure), in which case rescheduling or a full refund will be offered.\n\n9. TRAVELER INFORMATION\nTo issue the voucher and allow entry to the experience, we request information about the lead traveler on the booking (name, national ID or equivalent document, email, and optionally phone number). It is the traveler''s responsibility to ensure this information is accurate and matches the document they will present on the day of the experience.\n\n10. SELLERS\nSellers (hotels, concierges, agencies, or individuals with their own code) act independently and are not employees, representatives, or partners of Tango QR. Their role is to promote experiences through their personal code or QR, and in some cases to collect cash payment on behalf of the operator. Tango QR is not responsible for any agreement, promise, or information provided by a seller that is not reflected in these Terms or in the details of each experience published on the Platform.\n\n11. INTELLECTUAL PROPERTY\nThe name, logo, design, and content of the Platform are the property of Tango QR or its licensors and are protected under applicable intellectual property law. Reproduction, distribution, or commercial use without prior written authorization is prohibited.\n\n12. LIMITATION OF LIABILITY\nTango QR facilitates the booking and payment of experiences operated by third parties. The service itself (dinner, show, drinks, artistic quality, venue conditions) is the responsibility of the corresponding tango house. Tango QR is not liable for indirect damages, loss of enjoyment, or other harm arising from the operator''s provision of the service, without prejudice to assisting the traveler with a claim against the operator when requested to do so.\n\n13. CHANGES TO THESE TERMS\nTango QR may update these Terms and Conditions at any time to reflect operational, legal, or service changes. The version in effect is always the one published on this page, along with its last-updated date. Continued use of the Platform after an update constitutes acceptance of the new terms.\n\n14. GOVERNING LAW AND JURISDICTION\nThese Terms are governed by the laws of Argentina. Any dispute arising from their interpretation or application shall be submitted to the ordinary courts of the City of Buenos Aires, without prejudice to any rights the consumer may have under applicable consumer protection law.\n\n15. CONTACT\nFor any questions about these Terms and Conditions or about a specific booking, please write to us by email via the Contact section of the Platform."
  }'::jsonb,
  'Contenido de la página Términos y Condiciones (bilingüe).'
)
ON CONFLICT (key) DO NOTHING;
